INSERT INTO places (id, city_id, place_name, name_english, ai_summary, suggested_duration, best_time_to_visit, place_tip, advanced_booking, state_name, sunrise_view, sunset_view, sunrise_time, sunset_time, cost, rating_tourist_priority, rating_traveler_experience, latitude, longitude, address, official_website, rank_score, created_at, google_place_id, category, cuisine, price_band, veg_flag, source, updated_at, verification_status, verification_notes, verified_at) VALUES
('200001','2001','Burj Khalifa','Burj Khalifa','Dubai''s 828-metre landmark and the world''s tallest building, with observation decks on levels 124, 125 and 148.','2-3 hours','Evening','Book a sunset slot early; prime-time observation tickets sell first.','Timed ticket strongly recommended','Dubai','0','1','','','At the Top tickets from AED 159 (Visit Dubai; dynamic pricing applies)',5.0,4.8,25.1972,55.2744,'1 Sheikh Mohammed bin Rashid Blvd, Downtown Dubai, Dubai','https://www.burjkhalifa.ae/',0.99,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 12:00:00','verified','Visit Dubai confirms Burj Khalifa is 828m tall and lists At the Top observation decks on floors 124/125 plus level 148; ticket pricing starts at AED159. Admission is timed and operating slots vary by date, so flat daily hours are intentionally not asserted. [Sources: visitdubai.com; burjkhalifa.ae]','2026-10-01'),
('200002','2001','Dubai Frame','Dubai Frame','A 150-metre landmark in Zabeel Park framing panoramic views of old and modern Dubai.','1-2 hours','Evening','Go before sunset to see both daylight and city lights from the sky bridge.','Advance ticket recommended on weekends','Dubai','0','1','','','Adult AED 52.50; child age 3-11 AED 21 (Visit Dubai)',4.7,4.5,25.2355,55.3004,'Zabeel Park, Za''abeel 1, Dubai','https://www.dubaiframe.ae/',0.93,'2026-10-01 12:00:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 12:00:00','verified','Visit Dubai lists 9:00 AM-9:00 PM daily and AED52.50 adult / AED21 child pricing. Public map data places the attraction at approximately 25.2355,55.3004. [Sources: visitdubai.com; dubaiframe.ae]','2026-10-01'),
('200003','2001','Museum of the Future','Museum of the Future','Dubai''s torus-shaped future museum exploring science, technology, space, health and emerging ideas.','2-3 hours','Morning','Check live operating status before traveling; the current closure information conflicts across official channels.','Timed booking normally required','Dubai','0','0','','','Temporarily closed; prior standard admission AED 169',4.8,4.5,25.2191,55.2821,'Sheikh Zayed Road, Trade Centre 2, Dubai','https://museumofthefuture.ae/en',0.55,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 16:00:00','verified','CURRENT STATUS verified 2026-10-01: Museum of the Future''s official FAQ says it has been temporarily closed since early September 2026 and is expected to reopen in Q1 2027. Older plan/visit pages still expose pre-closure hours/pricing and must not be treated as current. [Primary: museumofthefuture.ae official FAQ]','2026-10-01'),
('200004','2001','Dubai Aquarium & Underwater Zoo','Dubai Aquarium and Underwater Zoo','A large aquarium and underwater zoo inside Dubai Mall, known for its tunnel, sharks and rays.','2 hours','Afternoon','Pair it with Burj Khalifa and the Dubai Fountain in one Downtown visit.','Advance ticket useful in peak periods','Dubai','0','0','','','Paid; ticket packages vary by experience and residency',4.6,4.4,25.1977,55.2789,'Dubai Mall, Downtown Dubai, Dubai','https://www.thedubaiaquarium.com/',0.9,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 12:00:00','verified','Official ticket site lists Mon-Thu 11 AM-9 PM and Fri-Sun 10 AM-9 PM, last entry 8:15 PM; open 365 days a year. Ticket packages are dynamic, so no single general price is stored. [Source: thedubaiaquarium.com]','2026-10-01'),
('200005','2001','Jumeirah Mosque','Jumeirah Mosque','A landmark white-stone mosque known for its public cultural tours and Fatimid-inspired architecture.','1-1.5 hours','Morning','Join the cultural tour rather than visiting only for an exterior photo.','Guided tour recommended','Dubai','0','0','','','Guided visit ticketed; confirm current SMCCU rate',4.5,4.6,25.233,55.2654,'Jumeirah Beach Road, Jumeirah 1, Dubai','https://www.cultures.ae/',0.88,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Visit Dubai confirms the mosque welcomes visitors of all faiths and lists 75-minute guided tours six days a week at 10 AM through the Sheikh Mohammed Centre for Cultural Understanding. Exact weekly off-day/rate should be confirmed from SMCCU before publishing as a fixed schedule. [Sources: visitdubai.com; cultures.ae]','2026-10-01'),
('200006','2001','Al Shindagha Museum','Al Shindagha Museum','A heritage museum district on Dubai Creek covering the city''s maritime history, perfume traditions and Emirati life.','2-3 hours','Morning','Allow extra time for the Perfume House and the Creek-focused galleries.','Online ticket optional','Dubai','0','1','','','Adult AED 35; child/student category AED 20 (Visit Dubai ticketing)',4.6,4.6,25.2665,55.289,'Al Shindagha, Dubai Creek, Dubai','https://alshindagha.dubaiculture.gov.ae/',0.89,'2026-10-01 12:00:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 12:00:00','verified','Dubai Culture museum brochure lists daily 10 AM-8 PM. Visit Dubai ticketing lists AED35 adult and AED20 child ticket categories. Location approximately 25.2665,55.2890 from OpenStreetMap-derived public map data. [Sources: dubaiculture.gov.ae; visitdubai.com]','2026-10-01'),
('200007','2001','Etihad Museum','Etihad Museum','A museum at the historic Union House site explaining the formation of the United Arab Emirates and its modern history.','1.5-2 hours','Morning','Visit early, then continue along Jumeirah toward the mosque and coast.','No advance booking normally required','Dubai','0','0','','','Adult AED 25; student age 5-24 AED 10; under 5 free',4.5,4.5,25.2392,55.2693,'1 Jumeirah Street, Al Mina, Dubai','https://etihadmuseum.dubaiculture.gov.ae/',0.87,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Dubai Culture material lists daily 10 AM-8 PM, last entry 7 PM, guided tours at 12 PM and 5 PM; adult AED25, student AED10, under-5 free. Coordinates confirmed by Wikidata. [Source: Dubai Culture / Etihad Museum]','2026-10-01'),
('200008','2001','Dubai Gold Souk','Gold Souk','Dubai''s historic precious-metals market in Deira, packed with gold, jewellery, gems and traditional trading shops.','1-2 hours','Evening','Compare several shops before buying and ask for the daily gold rate before negotiating workmanship charges.','','Dubai','0','0','','','Free to visit; purchases extra',4.5,4.4,25.2719,55.2963,'Deira, Dubai','',0.86,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Visit Dubai confirms Gold Souk is free to visit and says most shops operate about 10 AM-10 PM, with individual store hours varying. [Source: visitdubai.com]','2026-10-01'),
('200009','2001','Abra Creek Crossing','Dubai Creek Abra','A short ride on a traditional motorised abra linking Bur Dubai and Deira across Dubai Creek.','30-60 minutes','Evening','Cross near sunset and combine with the souks and Al Fahidi/Al Shindagha heritage areas.','','Dubai','0','1','','','AED 1 one-way on traditional crossing routes (Visit Dubai)',4.7,4.7,25.2672,55.2942,'Dubai Creek, Bur Dubai / Deira, Dubai','https://www.rta.ae/',0.91,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Visit Dubai states traditional abras run every few minutes throughout the day across four Creek stations and the short one-way crossing costs AED1. Exact first/last departures vary by route; use RTA live schedule for production. [Sources: visitdubai.com; rta.ae]','2026-10-01'),
('200010','2001','The Dubai Fountain','Dubai Fountain','A choreographed water, light and music show on Burj Lake at the base of Burj Khalifa.','30-60 minutes','Evening','Arrive before the evening rush and watch from the Burj Lake promenade or Souk Al Bahar side.','','Dubai','0','1','','','Free from public viewing areas; paid boardwalk/boat options available',4.8,4.7,25.1955,55.2756,'Burj Lake, Downtown Dubai, Dubai','https://www.thedubaimall.com/',0.94,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Visit Dubai confirms evening shows every 30 minutes from 6 PM to 11 PM, with limited afternoon shows as well; the fountain reopened on 1 Oct 2025 after refurbishment. [Source: visitdubai.com]','2026-10-01'),
('200011','2001','Dubai Marina Walk','Marina Walk','A seven-kilometre waterfront promenade around Dubai Marina lined with restaurants, towers and yacht views.','1-3 hours','Evening','Walk near sunset when temperatures are lower and the skyline begins to light up.','','Dubai','0','1','','','Free',4.5,4.6,25.076,55.14,'Dubai Marina, Dubai','https://www.dubai-marina.com/dubai-marina-walk/',0.86,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Visit Dubai describes Marina Walk as a 7 km promenade that is free to visit and open at all hours; individual businesses along it have their own schedules. [Source: visitdubai.com]','2026-10-01'),
('200012','2001','Ski Dubai','Ski Dubai','An indoor ski slope and snow park inside Mall of the Emirates with skiing, snow play and penguin experiences.','3-5 hours','Afternoon','Reserve lessons or premium experiences ahead; basic snow-park access is easier to arrange.','Advance booking recommended','Dubai','0','0','','','Paid; packages vary by slope/snow-park experience',4.5,4.5,25.1172,55.1983,'Mall of the Emirates, Sheikh Zayed Road, Dubai','https://www.skidxb.com/',0.87,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 12:00:00','verified','Visit Dubai ticketing lists Mon-Thu 10 AM-11 PM; Fri 10 AM-midnight; Sat-Sun 9 AM-midnight, with earlier last-entry cutoffs. Packages and prices vary. [Source: experiences.visitdubai.com]','2026-10-01'),
('200013','2001','Dubai Safari Park','Dubai Safari Park','A large wildlife park in Al Warqa with African, Asian, Arabian and safari zones and more than 3,000 animals.','4-6 hours','Morning','Visit when the new season is confirmed open; arrive at opening time for cooler weather and active animals.','Advance booking recommended once reopened','Dubai','0','0','','','Standard ticket listed around AED 50 before VAT (Visit Dubai; verify new season)',4.6,4.5,25.1778,55.4495,'Al Warqa 5, Dubai','https://dubaisafari.ae/',0.88,'2026-10-01 12:00:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 12:00:00','partial','As of 2026-10-01 the official site says the park is between seasons and will return for Season 8 in October 2026, but the exact reopening date was not captured. Official plan page lists 9 AM-6 PM; FAQ notes winter 9 AM-8 PM and summer 9 AM-6 PM. Visit Dubai lists standard entry around AED50 before VAT. Confirm new-season calendar before publishing live hours. [Sources: dubaisafari.ae; visitdubai.com]','2026-10-01'),
('200014','2001','Dubai Miracle Garden','Dubai Miracle Garden','A vast seasonal flower garden in Dubailand known for elaborate floral sculptures and installations.','2-3 hours','Evening','Only schedule this after the official site confirms the new season is open.','Advance ticket recommended in season','Dubai','0','1','','','Normal-season reference: adult AED 100; child age 3-12 AED 85 (Visit Dubai)',4.5,4.4,25.0594,55.2456,'Al Barsha South 3, Dubailand, Dubai','https://www.dubaimiraclegarden.com/',0.88,'2026-10-01 12:00:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:00:00','verified','CURRENT STATUS verified 2026-10-01: Dubai Miracle Garden official 2026/27 season information states Season 15 opens 8 Oct 2026 and lists daily hours 9 AM-9 PM. It is therefore closed through 7 Oct 2026. Ticket prices remain date/product sensitive. [Primary: dubaimiraclegarden.com]','2026-10-01'),
('200015','2001','Global Village Dubai','Global Village','A seasonal multicultural destination combining country pavilions, food, shopping, live entertainment and rides.','4-6 hours','Evening','Go after dark and allow several hours; the site is very large and highly seasonal.','Online ticket recommended','Dubai','0','0','','','Paid; Season 31 price not captured in this pass',4.7,4.6,25.0686,55.3063,'Wadi Al Safa 4, Dubai','https://www.globalvillage.ae/',0.92,'2026-10-01 12:00:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:00:00','verified','CURRENT STATUS verified 2026-10-01: Global Village Season 31 runs from 14 Oct 2026 into May 2027. Official Season-31 terms list Sun-Wed 4 PM-midnight and Thu-Sat 4 PM-1 AM; Tuesdays are commonly reserved for ladies, families and couples except designated public holidays/events. Closed before 14 Oct. [Primary: globalvillage.ae]','2026-10-01'),
('200016','2001','Al Fahidi Historical Neighbourhood','Al Fahidi Historical Neighbourhood','A preserved old-Dubai quarter of wind-tower houses, lanes, courtyards, galleries and cultural spaces beside Dubai Creek.','1-2 hours','Morning','Walk it together with the Creek abra, Textile Souk and Al Shindagha Museum.','','Dubai','0','0','','','Free to walk; individual museums/activities may charge',4.6,4.7,25.2635,55.2972,'Bur Dubai, Dubai','',0.89,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Visit Dubai identifies Al Fahidi Historical Neighbourhood as a core heritage area beside Dubai Creek. Note that nearby Al Fahidi Fort/Dubai Museum is currently viewable only from outside because the museum is closed for renovations. [Sources: visitdubai.com]','2026-10-01'),
('200017','2001','Expo City Dubai','Expo City Dubai','The legacy city of Expo 2020, retaining Al Wasl Plaza, Terra, Alif and other interactive cultural and sustainability attractions.','Half day','Afternoon','Use the Expo 2020 Metro Station and check which pavilions are operating before arrival.','Attraction tickets optional','Dubai','0','1','','','Public areas free; most ticketed attractions from AED 50 (Visit Dubai)',4.5,4.4,24.9606,55.1506,'Expo Road, Dubai South, Dubai','https://www.expocitydubai.com/',0.85,'2026-10-01 12:00:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 12:00:00','verified','Visit Dubai states admission to Expo City itself is free and most attractions start at AED50. Current ticketing copy says public areas are open 24/7 while pavilion operating hours shown are about 10 AM-6 PM with last entry 5:30 PM; confirm each pavilion before use. [Sources: visitdubai.com; expocitydubai.com]','2026-10-01'),
('200018','2001','Arabian Tea House - Al Fahidi','Arabian Tea House','A heritage-style Emirati restaurant and cafe in Al Fahidi, known for traditional breakfasts, rice dishes, grills and tea.','1-1.5 hours','Morning','Pair breakfast here with an early walk through Al Fahidi before the midday heat.','','Dubai','0','0','','','Paid; menu pricing varies',4.5,4.6,25.2632,55.3002,'Al Fahidi Street, Bur Dubai, Dubai','https://arabianteahouse.com/',0.87,'2026-10-01 12:00:00',NULL,'restaurant','Emirati','mid','veg-options','own','2026-10-01 12:00:00','verified','Official Arabian Tea House contact page confirms the Al Fahidi branch and lists working hours 7:00 AM-11:00 PM. Visit Dubai describes the restaurant as an Emirati dining experience in Al Fahidi. [Sources: arabianteahouse.com; visitdubai.com]','2026-10-01'),
('200019','2001','3Fils Dubai','3Fils','A contemporary Asian restaurant at Jumeirah Fishing Harbour with Japanese influences and a casual waterfront setting.','1-2 hours','Evening','It is walk-in only; arrive before peak dinner time if you want a shorter wait.','Walk-ins only','Dubai','0','1','','','Paid; menu item pricing published on official site',4.7,4.7,25.227,55.2585,'Shop 02, Jumeirah Fishing Harbour 1, Al Urouba Street, Jumeirah 1, Dubai','https://www.3fils.com/',0.89,'2026-10-01 12:00:00',NULL,'restaurant','Contemporary Asian / Japanese','premium','veg-options','own','2026-10-01 12:00:00','verified','Official 3Fils site confirms the Dubai flagship at Jumeirah Fishing Harbour, open daily 12 PM-11:30 PM and walk-ins only. The site publishes a live AED menu and current restaurant recognition. [Source: 3fils.com]','2026-10-01'),
('200020','2001','Al Ustad Special Kabab','Al Ustad Special Kabab','A long-running family-run Iranian kebab restaurant in Bur Dubai known for grilled meats, saffron rice and affordable portions.','1 hour','Evening','Combine it with an Old Dubai evening; expect a casual, busy dining room.','','Dubai','0','0','','','Budget; current numeric menu prices not captured in this pass',4.6,4.6,25.2585,55.2978,'Ground Floor, Bahwan Plaza, Al Mussallah Road, Mankhool, Dubai','https://alustadspecialkabab.has.restaurant/',0.86,'2026-10-01 12:00:00',NULL,'restaurant','Iranian / Persian','budget','veg-options','own','2026-10-01 12:00:00','verified','Visit Dubai confirms the restaurant, its Mankhool/Bur Dubai address and its reputation as an affordable Iranian kebab destination. Exact current operating hours were not captured from an authoritative source in this pass; keep hours flagged for confirmation. [Source: visitdubai.com]','2026-10-01'),
('200021','2001','Ravi Restaurant - Satwa','Ravi Restaurant','A famous casual Pakistani restaurant in Satwa serving curries, grilled meats, naan, biryani and lassi.','1 hour','Evening','Sit outside in cooler weather for the classic Satwa street-side experience.','','Dubai','0','0','','','Budget; Visit Dubai classifies it as $',4.5,4.5,25.2316,55.2765,'Shop 245, Al Dhiyafa Road, Al Satwa, Dubai','https://www.instagram.com/ravirestaurantsuae/',0.84,'2026-10-01 12:00:00',NULL,'restaurant','Pakistani','budget','veg-options','own','2026-10-01 12:00:00','verified','Visit Dubai confirms the Satwa location, cuisine, signature dishes and budget positioning. Exact current operating hours were not captured from an authoritative first-party source during this pass, so they remain unverified. [Source: visitdubai.com]','2026-10-01'),
('200022','2001','Al Seef Dubai','Al Seef','Creekside heritage-style district mixing traditional Gulf architecture, waterfront walks, shops, restaurants and abra access.','2-3 hours','Evening','Walk the heritage section near sunset, then continue along Dubai Creek after dark.','','Dubai','0','1','','','Public promenade free; shops and dining extra',4.5,4.4,25.26088,55.307,'Al Seef Street, Bur Dubai, Dubai','https://alseef.ae/',0.86,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Visit Dubai identifies Al Seef as a creekside heritage and leisure district. Current Visit Dubai guidance lists retail roughly 10 AM-10 PM Mon-Thu and to 11 PM Fri-Sun; restaurants generally later. Public waterfront access is not treated as a single gated attraction. Coordinates from OpenStreetMap/Mapcarta. [Sources: visitdubai.com; alseef.ae; OpenStreetMap]','2026-10-01'),
('200023','2001','The Beach, JBR','The Beach JBR','Popular beachfront promenade at Jumeirah Beach Residence with public sand, dining, shopping and family activities.','2-4 hours','Evening','Arrive before sunset for beach time and stay for the lit-up JBR promenade.','','Dubai','0','1','','','Public beach access free; activities and dining extra',4.6,4.5,25.0782,55.1338,'Jumeirah Beach Residence, Dubai','https://www.thebeach.ae/',0.88,'2026-10-01 12:00:00',NULL,'attraction',NULL,'mid','na','own','2026-10-01 16:00:00','verified','Verified as an open-access beachfront/promenade destination at JBR. There is no single attraction closing time; lifeguards, retail, restaurants and paid activities maintain their own schedules. [Sources: Visit Dubai; thebeach.ae]','2026-10-01'),
('200024','2001','Kite Beach Dubai','Kite Beach','Long public beach popular for swimming, kitesurfing, running, volleyball, food trucks and views toward Burj Al Arab.','2-4 hours','Morning','Go early for cooler weather and quieter sand; lifeguarded swimming areas are safest.','','Dubai','1','1','6:00 AM','6:00 PM','Free public beach; rentals and activities extra',4.6,4.6,25.164808,55.207336,'Jumeirah, Dubai','https://www.visitdubai.com/en/places-to-visit/kite-beach',0.89,'2026-10-01 12:00:00',NULL,'attraction',NULL,'budget','na','own','2026-10-01 12:00:00','verified','Visit Dubai describes Kite Beach as a public beach with 24/7 access and round-the-clock lifeguard coverage in designated areas; commercial facilities have their own schedules. Coordinates cross-checked with map sources. [Source: visitdubai.com]','2026-10-01'),
('200025','2001','Madinat Jumeirah','Madinat Jumeirah','Canal-side resort district with Souk Madinat Jumeirah, restaurants, traditional-style architecture and Burj Al Arab views.','2-3 hours','Evening','Walk the souk and canals at golden hour; waterfront terraces have excellent Burj Al Arab views.','Restaurant booking recommended for prime dinner tables','Dubai','0','1','','','Free to enter public areas; dining, abra rides and activities extra',4.7,4.6,25.1336,55.1853,'King Salman Bin Abdulaziz Al Saud St, Dubai','https://www.jumeirah.com/en/stay/dubai/madinat-jumeirah',0.91,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 12:00:00','verified','Visit Dubai lists Souk Madinat Jumeirah shops around 10 AM-11 PM and restaurants roughly 8 AM-2 AM, while hotel/resort facilities vary. [Sources: visitdubai.com; jumeirah.com]','2026-10-01'),
('200026','2001','Aquaventure World','Aquaventure Waterpark','Large Atlantis The Palm waterpark with major slides, river rides, family play zones and private-beach access.','Full day','Morning','Arrive at opening; a full day is justified if you want the headline slides and family areas.','Advance ticket recommended','Dubai','0','0','','','Paid admission; dynamic ticket pricing',4.8,4.7,25.1311,55.1167,'Atlantis The Palm, Crescent Road, Palm Jumeirah, Dubai','https://www.aquaventureworld.com/',0.95,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 16:00:00','verified','Official Aquaventure World currently lists the waterpark open 10 AM-6 PM daily. Ticket prices are dynamic/date-specific. [Primary: aquaventureworld.com]','2026-10-01'),
('200027','2001','IMG Worlds of Adventure','IMG Worlds of Adventure','Huge indoor theme park with Marvel, Cartoon Network, dinosaur and family entertainment zones.','5-7 hours','Afternoon','Because it is indoors, it works especially well during the hottest months.','Advance ticket recommended on weekends','Dubai','0','0','','','Paid admission; check live ticket price',4.6,4.5,25.0813964,55.3182833,'City of Arabia, Sheikh Mohammed Bin Zayed Road, Dubai','https://www.imgworlds.com/',0.9,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 12:00:00','verified','Official/current listings show Sun-Thu about 12 PM-10 PM and Fri-Sat about 12 PM-11 PM; special-event schedules can differ. Coordinates cross-checked against mapping sources. [Sources: imgworlds.com; visitdubai.com]','2026-10-01'),
('200028','2001','AYA Universe','AYA Universe','Immersive digital-art attraction at Wafi City with interactive light, sound and projection environments.','1.5-2 hours','Afternoon','Allow time to revisit the larger rooms; effects change as you move through them.','Timed/advance ticket recommended','Dubai','0','0','','','Paid admission; check current online price',4.5,4.5,25.229,55.3187,'Wafi City, Oud Metha Road, Dubai','https://www.aya-universe.com/',0.86,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 12:00:00','verified','Official site currently lists Sun-Thu approximately 10 AM-10 PM and Fri-Sat approximately 10 AM-midnight, with last admission before closing. [Source: aya-universe.com]','2026-10-01'),
('200029','2001','The View at The Palm','The View at The Palm','Palm Tower observation deck overlooking Palm Jumeirah, Dubai Marina and the Arabian Gulf.','1-2 hours','Evening','Sunset slots are popular; book ahead if the view is a priority.','Timed ticket recommended','Dubai','0','1','','','Paid admission; ticket tiers vary',4.7,4.6,25.11397,55.13983,'The Palm Tower, Palm Jumeirah, Dubai','https://www.theviewpalm.ae/',0.92,'2026-10-01 12:00:00',NULL,'attraction',NULL,'premium','na','own','2026-10-01 12:00:00','verified','Official site currently lists daily access around 10 AM-7 PM; timed products and premium decks may have separate schedules. Coordinates confirmed by OpenStreetMap/Commons. [Sources: theviewpalm.ae; OpenStreetMap]','2026-10-01'),
